import React from 'react';

export interface PictureSourceSet {
  sources: Record<string, string>;
  img: {
    src: string;
    w: number;
    h: number;
  };
}

export interface ResponsiveImageProps {
  src: PictureSourceSet | string;
  alt: string;
  width?: number;
  height?: number;
  sizes?: string;
  className?: string;
  pictureClassName?: string;
  priority?: boolean;
  decorative?: boolean;
}

/**
 * Renders responsive AVIF / WebP <picture> sources generated by vite-imagetools
 * when available, gracefully falling back to a sized <img> element.
 * Reserves explicit width & height attributes to guarantee CLS = 0.
 */
export const ResponsiveImage: React.FC<ResponsiveImageProps> = ({
  src,
  alt,
  width,
  height,
  sizes = '100vw',
  className = '',
  pictureClassName = '',
  priority = false,
  decorative = false,
}) => {
  const isPicture = typeof src === 'object' && src !== null && 'img' in src;
  const imgSrc = isPicture ? src.img.src : src;
  const imgWidth = isPicture ? src.img.w : width;
  const imgHeight = isPicture ? src.img.h : height;

  const loading = priority ? 'eager' : 'lazy';
  const decoding = priority ? 'sync' : 'async';

  const imgProps: React.ImgHTMLAttributes<HTMLImageElement> & { fetchPriority?: 'high' | 'low' | 'auto' } = {
    src: imgSrc,
    alt: decorative ? '' : alt,
    width: imgWidth,
    height: imgHeight,
    loading,
    decoding,
    fetchPriority: priority ? 'high' : 'auto',
    className,
    ...(decorative ? { 'aria-hidden': true } : {}),
  };

  if (!isPicture || !src.sources) {
    return <img {...imgProps} />;
  }

  return (
    <picture className={pictureClassName || undefined}>
      {Object.entries(src.sources).map(([format, srcset]) => (
        <source
          key={format}
          type={`image/${format === 'jpg' ? 'jpeg' : format}`}
          srcSet={srcset}
          sizes={sizes}
        />
      ))}
      <img {...imgProps} />
    </picture>
  );
};

export default ResponsiveImage;
